contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // the deployer/owner of C was msg.sender at C construction; when the checker deploys C
        // it will set owner to that deployer. In this test we are the InvMutTest contract,
        // not the original deployer, so record address(c).balance initially and owner via public getter.
        deployer = c.owner();
    }

    // single public test function as required
    function run(address caller, uint amount, bool callWithdrawAll, bool callWithdraw, bool callSend) public payable {
        require(true);

        // To be able to send Ether to c, ensure this contract has enough balance if needed.
        // If amount > 0 we will send it to c using receive on c by calling address(c).call with value.
        if (amount > 0) {
            require(address(this).balance >= amount, "not enough balance for funding");
            // send Ether into c by calling receive() via a plain call with value
            (bool s,) = address(c).call{value: amount}("");
            // ignore success: receive reverts only on overflow check in C which cannot fail for uint increment here
            // but keep flow; we don't require success so tests explore both cases
        }

        // read observable state before operations
        uint balanceBefore = address(c).balance;
        address owner = c.owner();

        // prepare to record whether calls reverted
        bool revertedWithdrawAll = false;
        bool revertedWithdraw = false;
        bool revertedSend = false;

        // We must make the state-changing calls as top-level statements.
        if (callWithdrawAll) {
            try c.withdrawAll() {
                revertedWithdrawAll = false;
            } catch {
                revertedWithdrawAll = true;
            }
        }

        if (callWithdraw) {
            try c.withdraw(amount) {
                revertedWithdraw = false;
            } catch {
                revertedWithdraw = true;
            }
        }

        if (callSend) {
            // send to caller address (an arbitrary input) via sendMoney
            try c.sendMoney(caller, amount) {
                revertedSend = false;
            } catch {
                revertedSend = true;
            }
        }

        // Observables after operations
        uint balanceAfter = address(c).balance;
        address ownerAfter = c.owner();

        // General rule to assert:
        // 1) owner never changes (owner stays equal to initial owner)
        // 2) If any of the owner-only methods did NOT revert, then msg.sender for C-call must have been the owner.
        //    Since calls to C are made from this InvMutTest contract, the only way they succeed is if owner == address(this).
        //    So we assert: if any of the three calls succeeded, then owner == address(this).
        // 3) Additionally, if withdrawAll succeeded then the contract balance must be zero afterwards.

        assert(
            owner == ownerAfter
            && (
                // if any succeeded then owner must be this contract
                (!revertedWithdrawAll || !revertedWithdraw || !revertedSend) ? (owner == address(this)) : true
            )
            && (
                // if withdrawAll succeeded then balanceAfter == 0
                revertedWithdrawAll ? true : (balanceAfter == 0)
            )
        );
    }

    // allow this contract to receive Ether so we can fund C
    receive() external payable {}
}

