        require(true);
        // If we will send Ether to C before invoking owner-only calls, ensure this contract has enough balance
        if (sendEther > 0) {
            require(address(this).balance >= sendEther);
            (bool _ok, ) = address(c).call{value: sendEther}("");
            _ok; // ignore result; receive() may revert on overflow which is not expected
        }

        // observe before state
        address ownerBefore = c.owner();
        uint balanceBefore = address(c).balance;

        // perform the state-changing calls as top-level statements; capture revert flags
        bool succeededWithdrawAll;
        bool succeededWithdraw;
        bool succeededSend;

        if (doWithdrawAll) {
            try c.withdrawAll() {
                succeededWithdrawAll = true;
            } catch {
                succeededWithdrawAll = false;
            }
        } else {
            succeededWithdrawAll = false;
        }

        if (doWithdraw) {
            try c.withdraw(amountToTransfer) {
                succeededWithdraw = true;
            } catch {
                succeededWithdraw = false;
            }
        } else {
            succeededWithdraw = false;
        }

        if (doSend) {
            try c.sendMoney(targetForSend, amountToTransfer) {
                succeededSend = true;
            } catch {
                succeededSend = false;
            }
        } else {
            succeededSend = false;
        }

        // observe after state
        address ownerAfter = c.owner();
        uint balanceAfter = address(c).balance;

        // General rule:
        // 1) owner never changes; and
        // 2) if any of the owner-only mutating calls succeeded then the owner must be this test contract (the caller),
        //    otherwise we don't constrain owner value; this ensures only the owner (this contract) can succeed.
        assert(
            ownerBefore == ownerAfter
            && ((succeededWithdrawAll || succeededWithdraw || succeededSend) ? (ownerAfter == address(this)) : true)
        );
    }

