contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // record who deployed C (its owner) by reading public owner
        deployer = c.owner();
    }

    // Single public test function: try calls that move Ether and assert owner-only behaviour
    // params: amount to deposit via receive, withdrawAmount to withdraw, sendTarget and sendValue
    function run(uint depositAmount, uint withdrawAmount, address payable sendTarget, uint sendValue) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");

        // Make sure deposit increase path: send Ether to c to trigger receive()
        // This is a top-level call that changes c's state
        c.f{value: 0}(); // harmless call to a non-existent function will revert; avoid — instead skip. But we must interact only via defined functions. To deposit, send Ether to c via low-level call from this contract:

        // perform deposit by sending Ether to c (triggers receive)
        (bool sent,) = address(c).call{value: depositAmount}("");
        // record balances and depositsCount before attempting owner-restricted calls
        uint cBalanceAfterDeposit = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // Try withdrawAmount via withdraw and capture revert
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Try withdrawAll and capture revert
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Try sendMoney and capture revert
        bool sendReverted;
        try c.sendMoney(sendTarget, sendValue) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // Determine whether this test contract is the recorded owner
        bool imOwner = (deployer == address(this));

        // General rule: if this contract is owner then none of the three calls should have reverted
        // and c's balance should be reduced at most by the amounts attempted; if not owner then all must revert
        if (imOwner) {
            // If owner, calls must not revert
            assert(!withdrawReverted && !withdrawAllReverted && !sendReverted);
            // And after successful owner withdrawals/send, c's balance cannot increase compared to post-deposit
            // (owner-only functions only remove funds). So final c.balance <= cBalanceAfterDeposit
            assert(address(c).balance <= cBalanceAfterDeposit);
        } else {
            // If not owner, none of the three owner-only functions should succeed
            assert(withdrawReverted && withdrawAllReverted && sendReverted);
        }
    }

    // Allow this contract to receive Ether to fund deposits/withdrawals
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // record the owner as reported by c at construction
        deployer = c.owner();
    }

    // Single public test function: deposit some Ether to C, then attempt owner-only actions
    function run(uint depositAmount, uint withdrawAmount, address payable sendTarget, uint sendValue) public payable {
        // Ensure this test contract has funds to deposit
        require(address(this).balance >= depositAmount, "insufficient balance to deposit");

        // Deposit Ether into C by calling it with value to trigger receive()
        (bool ok, ) = address(c).call{value: depositAmount}("");
        // deposit may revert only if receive() reverts; let that propagate (we don't catch here)
        require(ok, "deposit failed");

        // Record c's balance and depositsCount after deposit
        uint balanceAfterDeposit = address(c).balance;
        uint depositsAfter = c.depositsCount();

        // Try withdraw(uint)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Try withdrawAll()
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Try sendMoney(address,uint)
        bool sendReverted;
        try c.sendMoney(sendTarget, sendValue) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // Determine whether this InvMutTest contract was the owner recorded at construction
        bool imOwner = (deployer == address(this));

        // Final observed balance of c
        uint finalBalance = address(c).balance;

        // General rule:
        // - If this contract is the owner then none of the owner-only calls should revert
        //   and C's balance after these calls must be <= balance immediately after deposit.
        // - If this contract is not the owner then all three owner-only calls must have reverted.
        assert( (imOwner && (!withdrawReverted && !withdrawAllReverted && !sendReverted && finalBalance <= balanceAfterDeposit))
                || (!imOwner && (withdrawReverted && withdrawAllReverted && sendReverted)) );
    }

    // Allow this contract to receive Ether to fund deposits
    receive() external payable {}
}

