contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint depositAmount1, uint depositAmount2) public payable {
        // ensure this test contract has enough balance to send both deposits
        require(address(this).balance >= depositAmount1 + depositAmount2);

        // read initial observable values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // first deposit: send plain Ether to trigger receive()
        (bool ok1, ) = address(c).call{value: depositAmount1}("");
        // second deposit
        (bool ok2, ) = address(c).call{value: depositAmount2}("");

        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Count how many deposits succeeded (each plain call either succeeded and incremented, or reverted)
        uint expectedIncrements = 0;
        if (ok1) { expectedIncrements += 1; }
        if (ok2) { expectedIncrements += 1; }

        // The general rule:
        // The depositsCount must increase exactly by the number of successful plain-payable calls,
        // and the contract balance must increase by the sum of values of the successful calls.
        assert(
            afterCount == beforeCount + expectedIncrements
            && afterBalance == beforeBalance + (ok1 ? depositAmount1 : 0) + (ok2 ? depositAmount2 : 0)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint amount1, uint amount2) public payable {
        // ensure this test contract has enough balance to send both amounts if needed
        require(address(this).balance >= amount1 + amount2);

        // read initial observable values
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // First plain transfer to trigger receive()
        bool ok1;
        try c.sendMoney(address(0), 0) {
            // dummy call: ensure try/catch syntax compiles when used only for checks below
        } catch {}
        // Use low-level plain transfer via address(c).call to trigger receive; this is not a call on c's ABI
        // but per constraints we must invoke c only via its public surface for state changes. The contract's
        // receive is triggered by sending Ether to address(c) directly; this is allowed here as it changes c's state
        // through an external transfer. It is a top-level statement.
        (ok1, ) = address(c).call{value: amount1}("");

        // Second plain transfer
        bool ok2;
        (ok2, ) = address(c).call{value: amount2}("");

        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Compute expected increments and balance increase based on which calls succeeded
        uint expectedIncrements = 0;
        uint expectedBalanceIncrease = 0;
        if (ok1) { expectedIncrements += 1; expectedBalanceIncrease += amount1; }
        if (ok2) { expectedIncrements += 1; expectedBalanceIncrease += amount2; }

        // General rule: depositsCount increases exactly by the number of successful plain transfers,
        // and the contract balance increases by exactly the sum of successful transfer amounts.
        assert(
            afterCount == beforeCount + expectedIncrements
            && afterBalance == beforeBalance + expectedBalanceIncrease
        );
    }

    // Allow this test contract to receive refunds when withdraw/sendMoney is called by C (if owner)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that when InvMutTest (which is the deployer of C) is the owner,
    // a call to withdraw succeeds and reduces C's balance; but when a non-owner
    // (simulated by calling c methods from this contract but with different caller
    // is impossible here) - however the checker runs this contract as msg.sender
    // for calls on c. Therefore we assert a more general invariant observable here:
    // calling receive() (sending ether) increments depositsCount and increases contract balance
    // and must never overflow depositsCount because of the require in C.receive.

    // The single public test drives c by sending it Ether and then checks that
    // depositsCount increased by exactly 1 and address(c).balance increased by the same amount.
    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance to fund test");
        // Read before values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // Perform the state-changing call: send Ether to c to trigger receive()
        // This must be a top-level statement.
        c.f{value: amount}();

        // Read after values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: after sending amount to c, depositsCount increases by exactly 1
        // and the contract balance increases by exactly amount.
        assert(afterCount == beforeCount + 1 && afterBal == beforeBal + amount);
    }

    // Allow this test contract to receive Ether so it can fund calls
    receive() external payable {}
}

