            // afterBalance1 must equal beforeBalance (withdrawAll had no effect)
            // afterBalance2 must equal afterBalance1 (withdraw had no effect)
            assert(withdrawAllReverted == true && withdrawReverted == true && afterBalance1 == beforeBalance && afterBalance2 == afterBalance1);
