contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try withdrawAll and withdraw from either owner or non-owner
    // params:
    // - callWithdrawAll: if true, attempt withdrawAll(); otherwise attempt withdraw(amount)
    // - amount: value to pass to withdraw(uint)
    // - sendValue: Ether to first send into c via its receive (to ensure there is balance)
    // - asOwner: if true, the InvMutTest contract will be the owner (it is on fresh deploy),
    //            if false we attempt the same calls but from a different address by using
    //            c.sendMoney to transfer ownership-protected paths cannot change owner; instead
    //            we simulate a non-owner by making an external call from c to this contract
    // Note: Because the checker deploys C such that owner == msg.sender (the deployer), and
    // the deployer is the InvMutTest constructor caller (per problem statement), this test
    // treats this contract as owner. To simulate non-owner calls, we attempt a call that
    // originates from a third party by invoking c.sendMoney to an EOA is not possible here.
    // Instead we assert the general rule for calls made by this contract (the owner): that
    // such calls do NOT revert and reduce address(c).balance accordingly. For completeness,
    // we also attempt the call but catch reverts and assert that if it reverted then owner != this.

    function run(bool callWithdrawAll, uint amount, uint sendValue, bool _unused) public payable {
        require(address(this).balance >= sendValue, "insufficient test balance");

        // Fund c so withdraw(…) or withdrawAll can actually transfer value out.
        if (sendValue > 0) {
            // call receive by sending Ether to c
            (bool ok, ) = address(c).call{value: sendValue}("");
            // the receive might revert on overflow check (should not), but we don't require ok here
        }

        uint beforeBalance = address(c).balance;
        address ownerBefore = c.owner();

        bool reverted;
        // perform the deciding call: either withdrawAll() or withdraw(amount)
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBalance = address(c).balance;

        // General rule asserted:
        // If the call did not revert, then the caller must have been the owner (which for this test is true)
        // and the contract's balance must be less than or equal to beforeBalance (funds can only be transferred out).
        // If the call reverted, then ownerBefore != address(this) OR the attempted withdraw value exceeded balance.
        // Expressed as a single assert combining these cases.
        assert(
            // success case: not reverted implies ownerBefore == address(this) and afterBalance <= beforeBalance
            (!reverted && ownerBefore == address(this) && afterBalance <= beforeBalance)
            // revert case: either owner mismatch or attempted withdraw more than available (so no balance decrease)
            || (reverted && (ownerBefore != address(this) || (callWithdrawAll == false && amount > beforeBalance)))
        );
    }

    receive() external payable {}
}

